void dbReader::collision_refresh_initial()
{
	int nn = (int)nodeList.size();
	for (int i=0;i<nn;i++)
	{
		int vpn = (int)nodeList[i]->getvertex()->size();
		if (vpn==3)
		{
			point3D *v1 = nodeList[i]->getvertex()->at(0);
			point3D *v2 = nodeList[i]->getvertex()->at(1);
			point3D *v3 = nodeList[i]->getvertex()->at(2);
			if (!v1->getab()->get_attach() || !v1->getba()->get_attach() ||
				!v2->getab()->get_attach() || !v2->getba()->get_attach() ||
				!v3->getab()->get_attach() || !v3->getba()->get_attach())
			{
				point3D *V1 = NULL;
				if      (v1->getab()->get_attach() && v1->getba()->get_attach()) {V1 = v1;}
				else if (v2->getab()->get_attach() && v2->getba()->get_attach()) {V1 = v2;}
				else if (v3->getab()->get_attach() && v3->getba()->get_attach()) {V1 = v3;}
				point3D *V2 = V1->getba()->get_Neighbor()->p1();
				point3D *V3 = V1->getab()->get_Neighbor()->p2();
				cell *C2 = V2->getab()->Cell();
				cell *C3 = V3->getba()->Cell();
				int c2pn = (int)C2->get_pairs()->size();
				for (int j=0;j<c2pn;j++)
				{
					if      (C2->get_pairs()->at(j)->get_I1()==C2 && C2->get_pairs()->at(j)->get_I2()==C3)
					{
						if ((int)C2->get_pairs()->at(j)->MP()->size()==0)
						{
							mergepair *Mp = new mergepair(0,V2,V2,V3,V3);
							C2->get_pairs()->at(j)->push_MP(Mp);
						}
						break;
					}
					else if (C2->get_pairs()->at(j)->get_I2()==C2 && C2->get_pairs()->at(j)->get_I1()==C3)
					{
						if ((int)C2->get_pairs()->at(j)->MP()->size()==0)
						{
							mergepair *Mp = new mergepair(0,V3,V3,V2,V2);
							C2->get_pairs()->at(j)->push_MP(Mp);
						}
						break;
					}
				}
			}
		}
	}
}

void dbReader::collision_refresh(interpair *P)
{
	/*********************
	         \   /
	         s1 t2
			  | | 
			  | | 
			  | | 
			 t1 s2 
			 /   \ 
	*********************/
	point3D *s1,*t1,*s2,*t2,*e,*f,*g,*h;
	for (int i=0;i<(int)P->MP()->size();i++)
	{
		s1 = P->MP()->at(i)->S1();
		s2 = P->MP()->at(i)->S2();
		t1 = P->MP()->at(i)->T1();
		t2 = P->MP()->at(i)->T2();
		int flags1 = 0;
		for (int ii=0;ii<(int)s1->getmp()->size();ii++)
		{
			if (s1->getmp()->at(ii)==t2) {flags1 = 1;break;}
		}
		if (flags1==1) // attached
		{
			e = s1;
			f = t1->getfp();
			g = t2;
			bool merge1 = false;
			while (f!=e->getrp() && !merge1)
			{
				e = e->getrp();
				g = g->getfp();
				int flagii = 0;
				for (int ii=0;ii<(int)e->getmp()->size();ii++)
				{
					if (e->getmp()->at(ii)==g) {flagii++;}
					if (flagii>0) break;
				}
				if (flagii==0) 
				{
					s1 = e->getfp();
					t2 = g->getrp();
					merge1 = true;
					break;
				}
			}
		}
		else if (flags1==0)// not attached
		{
			e = s1;
			f = t1->getfp();
			bool merge1 = false;
			while (f!=e->getfp() && !merge1) 
			{
				g = t2;
				h = s2->getrp();
				while (h!=g->getrp() && !merge1)
				{
					for (int j=0;j<(int)e->getmp()->size();j++)
					{
						if (g==e->getmp()->at(j)) 
						{
							merge1 = true;
							s1 = e;
							t2 = g;
							break;
						}
					}
					g = g->getrp();
				}
				e = e->getfp();
			}
		}
		int flags2 = 0;
		for (int ii=0;ii<(int)s2->getmp()->size();ii++)
		{
			if (s2->getmp()->at(ii)==t1) {flags2 = 1;break;}
		}
		if      (flags2==1) // attached
		{
			e = s2;
			f = t2->getfp();
			g = t1;
			bool merge2 = false;
			while (f!=e->getrp() && !merge2)
			{
				e = e->getrp();
				g = g->getfp();
				int flagii = 0;
				for (int ii=0;ii<(int)e->getmp()->size();ii++)
				{
					if (e->getmp()->at(ii)==g) {flagii++;}
					if (flagii>0) break;
				}
				if (flagii==0)
				{
					merge2 = true;
					s2 = e->getfp();
					t1 = g->getrp();
					break;
				}
			}
		}
		else if (flags2==0) // not attached
		{
			e = s2;
			f = t2->getfp();
			bool merge2 = false;
			while (f!=e->getfp() && !merge2)
			{
				g = t1;
				h = s1->getrp();
				while (h!=g->getrp() && !merge2)
				{
					for (int j=0;j<(int)e->getmp()->size();j++)
					{
						if (g==e->getmp()->at(j))
						{
							merge2 = true;
							s2 = e;
							t1 = g;
							break;
						}
					}
					g = g->getrp();
				}
				e = e->getfp();
			}
		}
		P->MP()->at(i)->setS1(s1);
		P->MP()->at(i)->setT1(t1);
		P->MP()->at(i)->setS2(s2);
		P->MP()->at(i)->setT2(t2);
	}
}

int dbReader::intersection_type(point3D *P1, point3D *P2)
{
	int index = -1; // -1: no intersection
	/************
		24
		||
		13--6
		|
		5
	************/
	double x1 = P1->getab()->p1()->x();
	double y1 = P1->getab()->p1()->y();
	double x2 = P1->getab()->p2()->x();
	double y2 = P1->getab()->p2()->y();

	double x3 = P2->getba()->p2()->x();
	double y3 = P2->getba()->p2()->y();
	double x4 = P2->getba()->p1()->x();
	double y4 = P2->getba()->p1()->y();

	double x5 = P1->getrp()->x();
	double y5 = P1->getrp()->y();
	double x6 = P2->getfp()->x();
	double y6 = P2->getfp()->y();

	double a = x1 - x2;
	double b = x4 - x3;
	double c = y1 - y2;
	double d = y4 - y3;
	double e = x4 - x2;
	double f = y4 - y2;
	double B = b*c - a*d;

	if (B==0)
	{
		if (x1==x3)
		{
			if      (x5!=x6 || y5!=y6) {index = 9;}
			else if (x5==x6 && y5==y6) {index = 10;} // redundant
		}
	}
	else
	{
		/***************************
		types:
		---------------------------
		3: 
		     e o
			    \/
				 \    o
				  \  /
				   \/
				   /\
                  /  \
			     /    o
			   \/
             g o
		--------------------------
		4:
                        o
			           /
			   e o    /
				  \/ /
				   \/
				   /\
                 \/  \
			   g o    \
				       \
			            o  
		---------------------------
		5:
		     e o    o
			    \/ /
				 \/    
				 /\  
				/  \
			   /    \
             \/      \
		   g o        o
	    ---------------------------
		6:	  
		     e o        o
			    \/     /
			     \    /
				  \  /
				   \/
				   /\
                 \/  \
			   g o    o    
		***************************/
		double tB = e*c - a*f;
		double sB = b*f - e*d;
		double t = tB/B;
		double s = sB/B;
		if      (abs(t-1)<0.000000001) {t = 1;}
		else if (abs(t)  <0.000000001) {t = 0;}
		if      (abs(s-1)<0.000000001) {s = 1;}
		else if (abs(s)  <0.000000001) {s = 0;}

		if ((s>0 && s<1) && (t>0 && t<1))
		{
			if      (s<0.5 && t< 0.5) {index = 3;}
			else if (s>0.5 && t> 0.5) {index = 4;}
			else if (s>0.5 && t<=0.5) {index = 5;}
			else if (s<=0.5 && t>0.5) {index = 6;}
		}
		else if ((s==0 || s==1) && (t==0 || t==1))
		{
			if      (s ==1 && t == 1) {index = 1;}
			else if (s ==0 && t == 0) {index = 2;} // redundant
			else if (s ==0 && t == 1) {index = 7;} // redundant
			else if (s ==1 && t == 0) {index = 8;} // redundant
		}
		if (P1->getfp()->getmp()->size()>0)
		{
			for (int i=0;i<(int)P1->getfp()->getmp()->size();i++)
			{
				if      (P1->getfp()->getmp()->at(i)==P2->getrp()) {index = 2;break;}
				else if (P1->getfp()->getmp()->at(i)==P2)          {index = 7;break;}
			}
		}
		if (P1->getmp()->size()>0)
		{
			for (int i=0;i<(int)P1->getmp()->size();i++)
			{
				if      (P1->getmp()->at(i)==P2)          {index = 1;break;}
				else if (P1->getmp()->at(i)==P2->getrp()) {index = 8;break;}
			}
		}
		else
		{
			if (x1==x3 && y1==y3) {index = 1;}
		}
	}
	return index;
}

double dbReader::cell_distance(cell *C1, cell *C2)
{
	double dist = 0;
	/**********************************
	  o---o---o       o---o---o
	  |        \     /        |
	  o         o   o         o
	  |    O-->-|---|-<--O    |
	  o         o   o         o
	  |  C1    /     \   C2   |
	  o---o---o       o---o---o
	**********************************/
	double c1x = C1->get_center(0);
	double c1y = C1->get_center(1);
	double c2x = C2->get_center(0);
	double c2y = C2->get_center(1);
	double angle1_2 = vector2angle((c2x-c1x),(c2y-c1y));
	double dx1_2 = cos(angle1_2*PI/180);
	double dy1_2 = sin(angle1_2*PI/180);
	double angle2_1 = vector2angle((c1x-c2x),(c1y-c2y));
	double dx2_1 = cos(angle2_1*PI/180);
	double dy2_1 = sin(angle2_1*PI/180);
	int sn1 = (int)C1->get_sides()->size();
	int sn2 = (int)C2->get_sides()->size();
	point3D *max_plot_index1 = NULL;
	point3D *max_plot_index2 = NULL;
	double max_plot1 = -1000000;
	double max_plot2 = -1000000;
	for (int i=0;i<sn1;i++)
	{
		point3D *pmc1 = C1->get_sides()->at(i)->p1();
		double plot_c1 = pmc1->x()*dx1_2 + pmc1->y()*dy1_2;
		if (plot_c1>max_plot1)
		{
			max_plot1 = plot_c1;
			max_plot_index1 = pmc1;
		}
	}
	for (int i=0;i<sn2;i++)
	{
		point3D *pmc2 = C2->get_sides()->at(i)->p1();
		double plot_c2 = pmc2->x()*dx2_1 + pmc2->y()*dy2_1;
		if (plot_c2>max_plot2)
		{
			max_plot2 = plot_c2;
			max_plot_index2 = pmc2;
		}
	}
	dist = sqrt(
				(max_plot_index1->x()-max_plot_index2->x())*(max_plot_index1->x()-max_plot_index2->x())
		       +(max_plot_index1->y()-max_plot_index2->y())*(max_plot_index1->y()-max_plot_index2->y())
			   );
	return dist;
}

