			edgeList.push_back(E1);
			e_size++;
			edge *E2 = new edge(e_size-1,vertexList[v_size-1],f,h->getba()->Cell());
			edgeList.push_back(E2);
			e_size++;
			edge *E3 = new edge(e_size-1,e,g->getrp(),g->getab()->Cell());
			edgeList.push_back(E3);
			///////////////////////
			h->getba()->Cell()->removeside(h->getab());
			if (h->getab()->get_attach()) {h->getab()->get_Neighbor()->set_attach(0);}
			if (g->getba()->get_attach()) {g->getba()->get_Neighbor()->set_attach(0);}
			h->setab(E1);
			vertexList[v_size-1]->setba(E1);
			vertexList[v_size-1]->setab(E2);
			f->setba(E2);
			E1->set_Neighbor(g->getba());
			g->getba()->set_Neighbor(E1);
			E2->set_Neighbor(E3);
