						if ((int)g->getmp()->size()>0) {for (int l=0;l<(int)g->getmp()->size();l++) {g->getmp()->at(l)->removemp(g);}}
						e->clearmp();g->clearmp();
						e->pushmp(g);g->pushmp(e);
