int dbReader::cell_pick_response(int time)
{
	double LBD = BD*1.0;
	time_t t_b,t_e;
	t_b = clock();
	int nn = (int)nodeList.size();
	vector<point3D*> vert;
	for (int i=0;i<nn;i++)
	{
		if (nodeList[i]->get_in_global())
		{
			int pn = (int)nodeList[i]->getvertex()->size();
			if (pn==3)
			{
				point3D *p1 = nodeList[i]->getvertex()->at(0);
				point3D *p2 = nodeList[i]->getvertex()->at(1);
				point3D *p3 = nodeList[i]->getvertex()->at(2);
				int p1_tn = (int)p1->get_inner_at()->size();
				int p2_tn = (int)p2->get_inner_at()->size();
				int p3_tn = (int)p3->get_inner_at()->size();
				bool p12n = false;
				bool p22n = false;
				bool p32n = false;
				if (p1->getab()->get_attach() && p1->getba()->get_attach()) {p12n = true;}
				if (p2->getab()->get_attach() && p2->getba()->get_attach()) {p22n = true;}
				if (p3->getab()->get_attach() && p3->getba()->get_attach()) {p32n = true;}
				if (p12n && p22n && p32n)
				{
					if      (p1_tn==1)
					{
						double l1 = sqrt((p1->getfp()->x() - p1->getrp()->x())*(p1->getfp()->x() - p1->getrp()->x()) + 
										 (p1->getfp()->y() - p1->getrp()->y())*(p1->getfp()->y() - p1->getrp()->y()));
						double ang1 = p1->point_angle();
						if (l1<=LBD || ang1<B_ANGLE/2) 
						{
							vert.push_back(p1);
						}
					}
					else if (p2_tn==1)
					{
						double l2 = sqrt((p2->getfp()->x() - p2->getrp()->x())*(p2->getfp()->x() - p2->getrp()->x()) + 
										 (p2->getfp()->y() - p2->getrp()->y())*(p2->getfp()->y() - p2->getrp()->y()));
						double ang2 = p2->point_angle();
						if (l2<=LBD || ang2<B_ANGLE/2) 
						{
							vert.push_back(p2);
						}
					}
					else if (p3_tn==1)
					{
						double l3 = sqrt((p3->getfp()->x() - p3->getrp()->x())*(p3->getfp()->x() - p3->getrp()->x()) + 
										 (p3->getfp()->y() - p3->getrp()->y())*(p3->getfp()->y() - p3->getrp()->y()));
						double ang3 = p3->point_angle();
						if (l3<=LBD || ang3<B_ANGLE/2) 
						{
							vert.push_back(p3);
						}
					}
				}
				else if (p12n && !p22n && !p32n)
				{
					double ang1 = p1->point_angle();
					double ang2 = p2->point_angle();
					double ang3 = p3->point_angle();
					if      (ang1<ang2 && ang1<ang3 && ang1<B_ANGLE/2 && p1_tn==1) {vert.push_back(p1);}
					else if (ang2<ang3 && ang2<B_ANGLE && p2_tn==1) {vert.push_back(p2);}
					else if (ang3<ang2 && ang3<B_ANGLE && p3_tn==1) {vert.push_back(p3);}
				}
				else if (!p12n && p22n && !p32n)
				{
					double ang2 = p2->point_angle();
					double ang1 = p1->point_angle();
					double ang3 = p3->point_angle();
					if      (ang2<ang1 && ang2<ang3 && ang2<B_ANGLE/2 && p2_tn==1) {vert.push_back(p2);}
					else if (ang1<ang3 && ang1<B_ANGLE && p1_tn==1) {vert.push_back(p1);}
					else if (ang3<ang1 && ang3<B_ANGLE && p3_tn==1) {vert.push_back(p3);}
				}
				else if (!p12n && !p22n && p32n)
				{
					double ang3 = p3->point_angle();
					double ang1 = p1->point_angle();
					double ang2 = p2->point_angle();
					if      (ang3<ang1 && ang3<ang2 && ang3<B_ANGLE/2 && p3_tn==1) {vert.push_back(p3);}
					else if (ang1<ang2 && ang1<B_ANGLE && p1_tn==1) {vert.push_back(p1);}
					else if (ang2<ang1 && ang2<B_ANGLE && p2_tn==1) {vert.push_back(p2);}
				}
			}
			else if (pn>3)
			{
				point3D *p0 = nodeList[i]->getvertex()->at(0);
				double angle0 = p0->point_angle();
				for (int j=1;j<pn;j++)
				{
					point3D *pt = nodeList[i]->getvertex()->at(j);
					double anglet = pt->point_angle();
					if (angle0>anglet) {p0 = pt;angle0 = anglet;}
				}
				vert.push_back(p0);
			}
		}
	}
	for (int i=0;i<(int)vert.size();i++) 
	{
		int pick_index = pick_correction(vert[i]);
		if (pick_index>=0) {return pick_index;}
	}
	vert.clear();
	t_e = clock();
	cout<<"cell pick correction done: "<<(t_e-t_b)*0.001<<" seconds!\n";

	return -1;
}

void dbReader::cell_angle_response()
{
	for (int i=0;i<(int)cellList.size();i++)
	{
		if (!cellList[i]->Burry())
		{
			int flag = 0;
			int ind = -1;
			for (int j=0;j<(int)cellList[i]->get_pairs()->size();j++)
			{
				if (cellList[i]->get_pairs()->at(j)->MP()->size()>0) {flag++;ind = j;break;}
			}
			if (flag>0)
			{
				point3D *s,*t;
				if      (i==cellList[i]->get_pairs()->at(ind)->get_I1()->id())
				{
					s = cellList[i]->get_pairs()->at(ind)->MP()->at(0)->S1()->getfp();
					t = cellList[i]->get_pairs()->at(ind)->MP()->at(0)->S1();
				}
				else if (i==cellList[i]->get_pairs()->at(ind)->get_I2()->id())
				{
					s = cellList[i]->get_pairs()->at(ind)->MP()->at(0)->S2()->getfp();
					t = cellList[i]->get_pairs()->at(ind)->MP()->at(0)->S2();
				}
				while (s!=t)
				{
					if (s->getmp()->size()==0)
					{
						double angle = s->point_angle();
						if (angle>180) // relax
						/***********************
						    o        o
							|        |
							|        |
							o   ->   o  
						   /         |
					      /          |
					     o           o
						***********************/
						{
							double xn = (s->getrp()->x() + s->getfp()->x())/2;
							double yn = (s->getrp()->y() + s->getfp()->y())/2;
							s->setx(xn);
							s->sety(yn);
						}
					}
					s = s->getfp();
				}
			}
		}
	}
}

void dbReader::cell_mesh_generation(int time)
{
	time_t t_b,t_e;
	t_b = clock();
	int cn = (int)cellList.size();
    for (int i=0;i<cn;i++)
	{
		cell * Ci = cellList[i];
		if (Ci->Dead()) continue;
		cell_interior_resample(Ci,time);
		Ci->set_interior_refresh(0);
		Ci->refresh_AABB();
		if (Ci->Mark_number()==1) {Ci->setup_Mark_number(0);} // migrate reset to normal
	}
	t_e = clock();
	cout<<"cell inner mesh generation done: "<<(t_e-t_b)*0.001<<" seconds!\n";
}

void dbReader::node_merge(point3D* P1, point3D* P2)
{
	if (P1->get_node_id()!=P2->get_node_id())
	{
		node *N1 = P1->get_node_id();
		node *N2 = P2->get_node_id();
		if (P1->id()<P2->id())
		{
			int p2nn = (int)N2->getvertex()->size();
			for (int i=0;i<p2nn;i++)
			{
				N1->pushvertex(N2->getvertex()->at(i));
			}
			for (int i=0;i<p2nn;i++)
			{
				N2->getvertex()->at(i)->set_node_id(N1);
			}
			N2->set_in_global(0);
		}
		else
		{
			int p1nn = (int)N1->getvertex()->size();
			for (int i=0;i<p1nn;i++)
			{
				N2->pushvertex(N1->getvertex()->at(i));
			}
			for (int i=0;i<p1nn;i++)
			{
				N1->getvertex()->at(i)->set_node_id(N2);
			}
			N1->set_in_global(0);
		}
	}
}

void dbReader::node_remove_0(point3D* P)
{
	/*********************************
	 this vertex is still in the cell:
                      P
	    O------O------O
		O------O------O
	*********************************/
	if ((int)P->get_node_id()->getvertex()->size()>1)
	{
		P->get_node_id()->removevertex(P);
		int n_size = (int)nodeList.size();
		node *A = new node(n_size);
		nodeList.push_back(A);
		nodeList[n_size]->pushvertex(P);
		nodeList[n_size]->set_in_global(1);
		P->set_node_id(nodeList[n_size]);
	}
}

void dbReader::node_remove_1(point3D* P)
{
	/*********************************
	 this vertex is not in the cell 
	 any longer:
                      P
	    O------O------O
		O------O------O
	*********************************/
	if ((int)P->get_node_id()->getvertex()->size()==1)
	{
		P->set_in_cell(0);
		P->set_node_check(0);
		P->get_node_id()->set_in_global(0);
	}
	else if ((int)P->get_node_id()->getvertex()->size()>1)
	{
		P->set_in_cell(0);
		P->get_node_id()->removevertex(P);
		P->set_node_id(NULL);
		P->set_node_check(0);
	}
}

int dbReader::pick_correction(point3D* P)
{
	/****************************************************
	            R        F
	        ==>==O  C1  O==>==
			  t1 \\    // s2
			      \\  //     
			C2	 s1 OO t2    C3
				    || P

	  -------------------------------------------------
	  RP and PF must have neighbor edges
	  merge the triangle R-P-F
	****************************************************/
	if (P->get_in_cell())
	{
		cout<<"pick correction at point "<<P->id()<<" of cell "<<P->getab()->Cell()->id();
		int PC_s = P->getab()->Cell()->get_sides()->size();
		if (PC_s<=6) {cell_death_response(P->getab()->Cell());}
		else
		{
			point3D *F = P->getfp();
			point3D *R = P->getrp();
			if (P->getab()->get_attach() && P->getba()->get_attach())
			{
				point3D *s1 = P->getba()->get_Neighbor()->p1();
				point3D *t1 = P->getba()->get_Neighbor()->p2();
				point3D *s2 = P->getab()->get_Neighbor()->p1();
				point3D *t2 = P->getab()->get_Neighbor()->p2();
				if (s1==t2)
				{
					cell *C1 = R->getba()->Cell();
					cell *C2 = P->getba()->get_Neighbor()->Cell();
					cout<<", cells:"<<C1->id()<<","<<C2->id()<<endl;
					C1->removeside(P->getba());
					C1->removeside(P->getab());
					C2->removeside(P->getba()->get_Neighbor());
					C2->removeside(P->getab()->get_Neighbor());
					double xm = (R->x() + F->x())*0.5;
					double ym = (R->y() + F->y())*0.5;
					R->setfp(F->getfp());
					F->getfp()->setrp(R);
					R->setab(F->getab());
					F->getab()->reset_p1(R);
					vector<point3D*> Rmp; 
					for (int i=0;i<(int)R->getmp()->size();i++) {Rmp.push_back(R->getmp()->at(i));}
					vector<point3D*> Fmp; 
					for (int i=0;i<(int)F->getmp()->size();i++) 
					{
						if (F->getmp()->at(i)!=s2) {Fmp.push_back(F->getmp()->at(i));}
						F->getmp()->at(i)->removemp(F);
					}
					node_remove_1(F);
					t1->setrp(s2->getrp());
					s2->getrp()->setfp(t1);
					t1->setba(s2->getba());
					s2->getba()->reset_p2(t1);
					for (int i=0;i<(int)s2->getmp()->size();i++)
					{
						s2->getmp()->at(i)->removemp(s2);
					}
					node_remove_1(s2);
					P->get_node_id()->set_in_global(0);
					for (int i=0;i<(int)P->get_node_id()->getvertex()->size();i++) 
					{P->get_node_id()->getvertex()->at(i)->set_in_cell(0);}
					for (int i=0;i<(int)Fmp.size();i++)
					{
						cell *C1F = Fmp[i]->getba()->Cell();
						Fmp[i]->setx(xm);
						Fmp[i]->sety(ym);
						for (int j=0;j<(int)Rmp.size();j++)
						{
							cell *C1R = Rmp[j]->getab()->Cell();
							Rmp[j]->setx(xm);
							Rmp[j]->sety(ym);
							bool flag = true;
							for (int k=0;k<(int)C1F->get_pairs()->size();k++)
							{
								if (C1F->get_pairs()->at(k)->get_redundant()) continue;
								if ((C1F->get_pairs()->at(k)->get_I1()==C1F && C1F->get_pairs()->at(k)->get_I2()==C1R) ||
									(C1F->get_pairs()->at(k)->get_I2()==C1F && C1F->get_pairs()->at(k)->get_I1()==C1R))
								{
									flag = false;
									if ((int)C1F->get_pairs()->at(k)->MP()->size()==0)
									{
										if (C1F->get_pairs()->at(k)->get_I1()==C1F)
										{
											mergepair *MP = new mergepair(0,Fmp[i],Fmp[i],Rmp[j],Rmp[j]);
											C1F->get_pairs()->at(k)->push_MP(MP);
										}
										else
										{
											mergepair *MP = new mergepair(0,Rmp[j],Rmp[j],Fmp[i],Fmp[i]);
											C1F->get_pairs()->at(k)->push_MP(MP);
										}
									}
									break;
								}
							}
							if (flag)
							{
								int pair_n = (int)collisionpairList.size();
								interpair *P = new interpair(pair_n,C1F,C1R);
								collisionpairList.push_back(P);
								//int iptype = interpair_type(C1F,C1R);
								//collisionpairList[pair_n]->set_adhesion(adhesion_pair_class[iptype]);
								double adhesion_force = adhesion_pair_array[C1F->get_cell_type()][C1R->get_cell_type()];
								collisionpairList[pair_n]->set_adhesion(adhesion_force);
								collisionpairList[pair_n]->set_friction(adhesion_force);
								mergepair *MP = new mergepair(1,Fmp[i],Fmp[i],Rmp[j],Rmp[j]);
								collisionpairList[pair_n]->push_MP(MP);
								C1F->pushpair(collisionpairList[pair_n]);
								C1R->pushpair(collisionpairList[pair_n]);
							}
							Rmp[j]->pushmp(Fmp[i]);
							Fmp[i]->pushmp(Rmp[j]);
						}
						R->pushmp(Fmp[i]);
					}
					R->setx(xm);
					R->sety(ym);
					for (int i=0;i<(int)C1->get_pairs()->size();i++)
					{
						if (C1->get_pairs()->at(i)->get_redundant()) continue;
						for (int j=0;j<(int)C1->get_pairs()->at(i)->MP()->size();j++)
						{
							if (C1->get_pairs()->at(i)->MP()->at(j)->S1()==F) {C1->get_pairs()->at(i)->MP()->at(j)->setS1(R);}
							if (C1->get_pairs()->at(i)->MP()->at(j)->T1()==F) {C1->get_pairs()->at(i)->MP()->at(j)->setT1(R);}
							if (C1->get_pairs()->at(i)->MP()->at(j)->S2()==F) {C1->get_pairs()->at(i)->MP()->at(j)->setS2(R);}
							if (C1->get_pairs()->at(i)->MP()->at(j)->T2()==F) {C1->get_pairs()->at(i)->MP()->at(j)->setT2(R);}
							if (C1->get_pairs()->at(i)->MP()->at(j)->S1()==s2) {C1->get_pairs()->at(i)->MP()->at(j)->setS1(t1);}
							if (C1->get_pairs()->at(i)->MP()->at(j)->T1()==s2) {C1->get_pairs()->at(i)->MP()->at(j)->setT1(t1);}
							if (C1->get_pairs()->at(i)->MP()->at(j)->S2()==s2) {C1->get_pairs()->at(i)->MP()->at(j)->setS2(t1);}
							if (C1->get_pairs()->at(i)->MP()->at(j)->T2()==s2) {C1->get_pairs()->at(i)->MP()->at(j)->setT2(t1);}
						}
					}
					Rmp.clear();
					Fmp.clear();
					//
					cell_interior_resample(C1,0);
					cell_interior_resample(C2,0);
				}
				else
				{
					cell *C1 = R->getba()->Cell();
					cell *C2 = P->getba()->get_Neighbor()->Cell();
					cell *C3 = P->getab()->get_Neighbor()->Cell();
					cout<<", cells:"<<C1->id()<<","<<C2->id()<<","<<C3->id()<<endl;
					if (C1==C2 || C1==C3 || C2==C3)
					{
						cout<<"  -> error: pick gets stranded!"<<endl;
						return C1->id();
					}
					double xm = (R->x() + F->x())*0.5;
					double ym = (R->y() + F->y())*0.5;
					R->setfp(F->getfp());
					F->getfp()->setrp(R);
					R->setab(F->getab());
					F->getab()->reset_p1(R);
					R->setx(xm);
					R->sety(ym);
					C1->removeside(P->getba());
					C1->removeside(P->getab());
					vector<point3D*> Rmp;
					vector<point3D*> Fmp;
					for (int i=0;i<(int)R->getmp()->size();i++) {Rmp.push_back(R->getmp()->at(i));}
					for (int i=0;i<(int)F->getmp()->size();i++) {Fmp.push_back(F->getmp()->at(i));F->getmp()->at(i)->removemp(F);}
					for (int i=0;i<(int)P->getmp()->size();i++) {P->getmp()->at(i)->removemp(P);}
					node_remove_1(F);
					node_remove_1(P);
					node_merge(s2,t1);
					if (s1->getba()->get_attach() && t2->getab()->get_attach())
					{
						if ((s1->getba()->get_Pair()->get_I1()==C2 && s1->getba()->get_Pair()->get_I2()==C3) ||
							(s1->getba()->get_Pair()->get_I2()==C2 && s1->getba()->get_Pair()->get_I1()==C3))
						{
							interpair *P1 = s1->getba()->get_Pair(); // C2-C3
							interpair *P2 = s1->getab()->get_Pair(); // C1-C2
							interpair *P3 = t2->getba()->get_Pair(); // C1-C3
							s1->getab()->set_Pair(P1);
							s2->getab()->set_Pair(P1);
							for (int j=0;j<(int)P1->MP()->size();j++) // C2-C3
							{
								if (P1->MP()->at(j)->T1()==s1) {P1->MP()->at(j)->setT1(t1);}
								if (P1->MP()->at(j)->S1()==t2) {P1->MP()->at(j)->setS1(s2);}
								if (P1->MP()->at(j)->T2()==s1) {P1->MP()->at(j)->setT2(t1);}
								if (P1->MP()->at(j)->S2()==t2) {P1->MP()->at(j)->setS2(s2);}
							}
							for (int j=0;j<(int)P2->MP()->size();j++) // C1-C2
							{
								if (P2->MP()->at(j)->T1()==P)
								{
									P2->MP()->at(j)->setT1(R);
									P2->MP()->at(j)->setS2(t1);
								}
								if (P2->MP()->at(j)->T2()==P)
								{
									P2->MP()->at(j)->setT2(R);
									P2->MP()->at(j)->setS1(t1);
								}
							}
							for (int j=0;j<(int)P3->MP()->size();j++) // C1-C3
							{
								if (P3->MP()->at(j)->S1()==P)
								{
									P3->MP()->at(j)->setS1(R);
									P3->MP()->at(j)->setT2(s2);
								}
								if (P3->MP()->at(j)->S2()==P)
								{
									P3->MP()->at(j)->setS2(R);
									P3->MP()->at(j)->setT1(s2);
								}
								if (P3->MP()->at(j)->T1()==F) {P3->MP()->at(j)->setT1(R);}
								if (P3->MP()->at(j)->T2()==F) {P3->MP()->at(j)->setT2(R);}
							}
							int c1pn = (int)C1->get_pairs()->size();
							for (int i=0;i<c1pn;i++)
							{
								interpair *c1pi = C1->get_pairs()->at(i);
								for (int j=0;j<(int)c1pi->MP()->size();j++)
								{
									if (c1pi->MP()->at(j)->S1()==F) {c1pi->MP()->at(0)->setS1(R);}
									if (c1pi->MP()->at(j)->S2()==F) {c1pi->MP()->at(0)->setS2(R);}
									if (c1pi->MP()->at(j)->T1()==F) {c1pi->MP()->at(0)->setT1(R);}
									if (c1pi->MP()->at(j)->T2()==F) {c1pi->MP()->at(0)->setT2(R);}
								}
							}
						}
						else
						{
							int c1pn = (int)C1->get_pairs()->size();
							for (int i=0;i<c1pn;i++)
							{
								interpair *c1pi = C1->get_pairs()->at(i);
								if ((c1pi->get_I1()==C1 && c1pi->get_I2()!=C2 && c1pi->get_I2()!=C3) ||
									(c1pi->get_I2()==C1 && c1pi->get_I1()!=C2 && c1pi->get_I1()!=C3))
								{
									for (int j=0;j<(int)c1pi->MP()->size();j++)
									{
										if ((c1pi->MP()->at(j)->S1()==P && c1pi->MP()->at(j)->T1()==P) ||
											(c1pi->MP()->at(j)->S2()==P && c1pi->MP()->at(j)->T2()==P))
										{
											c1pi->remove_MP(c1pi->MP()->at(j));
											break;
										}
										else
										{
											if (c1pi->MP()->at(j)->S1()==F) {c1pi->MP()->at(j)->setS1(R);}
											if (c1pi->MP()->at(j)->S2()==F) {c1pi->MP()->at(j)->setS2(R);}
											if (c1pi->MP()->at(j)->T1()==F) {c1pi->MP()->at(j)->setT1(R);}
											if (c1pi->MP()->at(j)->T2()==F) {c1pi->MP()->at(j)->setT2(R);}
										}
									}
								}
								else if ((c1pi->get_I1()==C1 && c1pi->get_I2()==C2) ||
									(c1pi->get_I2()==C1 && c1pi->get_I1()==C2))
								{
									for (int j=0;j<(int)c1pi->MP()->size();j++)
									{
										if (c1pi->MP()->at(j)->T1()==P) 
										{
											c1pi->MP()->at(j)->setT1(R);
											c1pi->MP()->at(j)->setS2(t1);
										}
										if (c1pi->MP()->at(j)->T2()==P)
										{
											c1pi->MP()->at(j)->setT2(R);
											c1pi->MP()->at(j)->setS1(t1);
										}
									}
								}
								else if ((c1pi->get_I1()==C1 && c1pi->get_I2()==C3) ||
									(c1pi->get_I2()==C1 && c1pi->get_I1()==C3))
								{
									for (int j=0;j<(int)c1pi->MP()->size();j++)
									{
										if (c1pi->MP()->at(j)->S1()==P)
										{
											c1pi->MP()->at(j)->setS1(R);
											c1pi->MP()->at(j)->setT2(s2);
										}
										if (c1pi->MP()->at(j)->S2()==P)
										{
											c1pi->MP()->at(j)->setS2(R);
											c1pi->MP()->at(j)->setT1(s2);
										}
										if (c1pi->MP()->at(j)->T1()==F) {c1pi->MP()->at(j)->setT1(R);}
										if (c1pi->MP()->at(j)->T2()==F) {c1pi->MP()->at(j)->setT2(R);}
									}
								}
							}
							int c2pn = (int)C2->get_pairs()->size();
							for (int i=0;i<c2pn;i++)
							{
								interpair *c2pi = C2->get_pairs()->at(i);
								if (c2pi->get_redundant()) continue;
								if ((c2pi->get_I1()==C2 && c2pi->get_I2()==C3) ||
									(c2pi->get_I2()==C2 && c2pi->get_I1()==C3))
								{
									s1->getab()->set_Pair(c2pi);
									s2->getab()->set_Pair(c2pi);
									for (int j=0;j<(int)c2pi->MP()->size();j++)
									{
										if (c2pi->MP()->at(j)->T1()==s1) {c2pi->MP()->at(j)->setT1(t1);}
										if (c2pi->MP()->at(j)->S1()==t2) {c2pi->MP()->at(j)->setS1(s2);}
										if (c2pi->MP()->at(j)->T2()==s1) {c2pi->MP()->at(j)->setT2(t1);}
										if (c2pi->MP()->at(j)->S2()==t2) {c2pi->MP()->at(j)->setS2(s2);}
									}
									break;
								}
							}
						}
					}
					else if (!s1->getba()->get_attach() || !t2->getab()->get_attach())
					{
						int c1pn = (int)C1->get_pairs()->size();
						for (int i=0;i<c1pn;i++)
						{
							interpair *c1pi = C1->get_pairs()->at(i);
							if ((c1pi->get_I1()==C1 && c1pi->get_I2()!=C2 && c1pi->get_I2()!=C3) ||
								(c1pi->get_I2()==C1 && c1pi->get_I1()!=C2 && c1pi->get_I1()!=C3))
							{
								for (int j=0;j<(int)c1pi->MP()->size();j++)
								{
									if ((c1pi->MP()->at(j)->S1()==P && c1pi->MP()->at(j)->T1()==P) ||
										(c1pi->MP()->at(j)->S2()==P && c1pi->MP()->at(j)->T2()==P))
									{
										c1pi->remove_MP(c1pi->MP()->at(j));
										break;
									}
									else
									{
										if (c1pi->MP()->at(j)->S1()==F) {c1pi->MP()->at(j)->setS1(R);}
										if (c1pi->MP()->at(j)->S2()==F) {c1pi->MP()->at(j)->setS2(R);}
										if (c1pi->MP()->at(j)->T1()==F) {c1pi->MP()->at(j)->setT1(R);}
										if (c1pi->MP()->at(j)->T2()==F) {c1pi->MP()->at(j)->setT2(R);}
									}
								}
							}
							else if ((c1pi->get_I1()==C1 && c1pi->get_I2()==C2) ||
								(c1pi->get_I2()==C1 && c1pi->get_I1()==C2))
							{
								for (int j=0;j<(int)c1pi->MP()->size();j++)
								{
									if (c1pi->MP()->at(j)->T1()==P)
									{
										c1pi->MP()->at(j)->setT1(R);
										c1pi->MP()->at(j)->setS2(t1);
									}
									if (c1pi->MP()->at(j)->T2()==P)
									{
										c1pi->MP()->at(j)->setT2(R);
										c1pi->MP()->at(j)->setS1(t1);
									}
								}
							}
							else if ((c1pi->get_I1()==C1 && c1pi->get_I2()==C3) ||
								(c1pi->get_I2()==C1 && c1pi->get_I1()==C3))
							{
								for (int j=0;j<(int)c1pi->MP()->size();j++)
								{
									if (c1pi->MP()->at(j)->S1()==P)
									{
										c1pi->MP()->at(j)->setS1(R);
										c1pi->MP()->at(j)->setT2(s2);
									}
									if (c1pi->MP()->at(j)->S2()==P)
									{
										c1pi->MP()->at(j)->setS2(R);
										c1pi->MP()->at(j)->setT1(s2);
									}
									if (c1pi->MP()->at(j)->T1()==F) {c1pi->MP()->at(j)->setT1(R);}
									if (c1pi->MP()->at(j)->T2()==F) {c1pi->MP()->at(j)->setT2(R);}
								}
							}
						}
						int c2pn = (int)C2->get_pairs()->size();
						for (int i=0;i<c2pn;i++)
						{
							interpair *c2pi = C2->get_pairs()->at(i);
							if (c2pi->get_redundant()) continue;
							if ((c2pi->get_I1()==C2 && c2pi->get_I2()==C3) ||
								(c2pi->get_I2()==C2 && c2pi->get_I1()==C3))
							{
								s1->getab()->set_Pair(c2pi);
								s2->getab()->set_Pair(c2pi);
								for (int j=0;j<(int)c2pi->MP()->size();j++)
								{
									if (c2pi->MP()->at(j)->T1()==s1) {c2pi->MP()->at(j)->setT1(t1);}
									if (c2pi->MP()->at(j)->S1()==t2) {c2pi->MP()->at(j)->setS1(s2);}
									if (c2pi->MP()->at(j)->T2()==s1) {c2pi->MP()->at(j)->setT2(t1);}
									if (c2pi->MP()->at(j)->S2()==t2) {c2pi->MP()->at(j)->setS2(s2);}
								}
								break;
							}
						}
					}
					///////// edge merging //////////
					s1->getab()->set_Neighbor(s2->getab());
					s2->getab()->set_Neighbor(s1->getab());
					int Fmpn = (int)Fmp.size();
					if (Fmpn==0)
					{
						for (int i=0;i<(int)Rmp.size();i++)
						{
							Rmp[i]->setx(xm);
							Rmp[i]->sety(ym);
						}
					}
					else
					{
						for (int i=0;i<Fmpn;i++)
						{
							Fmp[i]->setx(xm);
							Fmp[i]->sety(ym);
							cell *C1F = Fmp[i]->getba()->Cell();
							for (int j=0;j<(int)Rmp.size();j++)
							{
								Rmp[j]->setx(xm);
								Rmp[j]->sety(ym);
								cell *C1R = Rmp[j]->getab()->Cell();
								bool flag = true;
								for (int k=0;k<(int)C1F->get_pairs()->size();k++)
								{
									if (C1F->get_pairs()->at(k)->get_redundant()) continue;
									if ((C1F->get_pairs()->at(k)->get_I1()==C1F && C1F->get_pairs()->at(k)->get_I2()==C1R) ||
										(C1F->get_pairs()->at(k)->get_I2()==C1F && C1F->get_pairs()->at(k)->get_I1()==C1R))
									{
										flag = false;
										if (C1F->get_pairs()->at(k)->MP()->size()==0)
										{
											if (C1F->get_pairs()->at(k)->get_I1()==C1F)
											{
												mergepair *MP = new mergepair(0,Fmp[i],Fmp[i],Rmp[j],Rmp[j]);
												C1F->get_pairs()->at(k)->push_MP(MP);
											}
											else
											{
												mergepair *MP = new mergepair(0,Rmp[j],Rmp[j],Fmp[i],Fmp[i]);
												C1F->get_pairs()->at(k)->push_MP(MP);
											}
										}
										break;
									}
								}
								if (flag)
								{
									int pair_n = (int)collisionpairList.size();
									interpair *P = new interpair(pair_n,C1F,C1R);
									collisionpairList.push_back(P);
									//int iptype = interpair_type(C1F,C1R);
									//collisionpairList[pair_n]->set_adhesion(adhesion_pair_class[iptype]);
									double adhesion_force = adhesion_pair_array[C1F->get_cell_type()][C1R->get_cell_type()];
									collisionpairList[pair_n]->set_adhesion(adhesion_force);
									collisionpairList[pair_n]->set_friction(adhesion_force);
									mergepair *MP = new mergepair(0,Fmp[i],Fmp[i],Rmp[j],Rmp[j]);
									collisionpairList[pair_n]->push_MP(MP);
									C1F->pushpair(collisionpairList[pair_n]);
									C1R->pushpair(collisionpairList[pair_n]);
								}
								Rmp[j]->pushmp(Fmp[i]);
								Fmp[i]->pushmp(Rmp[j]);
							}
							R->pushmp(Fmp[i]);
							Fmp[i]->pushmp(R);
						}
					}
					Rmp.clear();
					Fmp.clear();
					///////// pick check again /////////
					int node_vn = R->get_node_id()->getvertex()->size();
					if (node_vn>3)
					{
						point3D *np0 = R->get_node_id()->getvertex()->at(0);
						point3D *Rnp = R->getmp()->at(0);
						double angle0 = np0->point_angle();
						for (int jj=1;jj<node_vn;jj++)
						{
							point3D *npjj = R->get_node_id()->getvertex()->at(jj);
							double anglejj = npjj->point_angle();
							if (angle0>anglejj) {np0 = npjj;angle0 = anglejj;}
						}
						cout<<"    -> additional correction:";
						int adp0 = pick_correction(np0);
						if (adp0>=0) {return adp0;}
						if (Rnp->get_in_cell())
						{
							int node_vna = Rnp->get_node_id()->getvertex()->size();
							//cout<<"  -> node_vna: "<<node_vna<<endl;
							if (node_vna>3)
							{
								point3D *np0a = Rnp->get_node_id()->getvertex()->at(0);
								double angle0a = np0a->point_angle();
								for (int jj=1;jj<node_vna;jj++)
								{
									point3D *npjja = Rnp->get_node_id()->getvertex()->at(jj);
									double anglejja = npjja->point_angle();
									if (angle0a>anglejja) {np0a = npjja;angle0a = anglejja;}
								}
								cout<<"    -> additional correction:";
								int adp0a = pick_correction(np0a);
								if (adp0a>=0) {return adp0a;}
							}
						}
					}
					else if (node_vn==3)
					{
						point3D *p1 = R->get_node_id()->getvertex()->at(0);
						point3D *p2 = R->get_node_id()->getvertex()->at(1);
						point3D *p3 = R->get_node_id()->getvertex()->at(2);
						bool p12n = false;
						bool p22n = false;
						bool p32n = false;
						if (p1->getab()->get_attach() && p1->getba()->get_attach()) {p12n = true;}
						if (p2->getab()->get_attach() && p2->getba()->get_attach()) {p22n = true;}
						if (p3->getab()->get_attach() && p3->getba()->get_attach()) {p32n = true;}
						if (p12n && p22n && p32n)
						{
							double ang1 = p1->point_angle();
							double ang2 = p2->point_angle();
							double ang3 = p3->point_angle();
							double l1 = sqrt((p1->getfp()->x() - p1->getrp()->x())*(p1->getfp()->x() - p1->getrp()->x()) + 
								(p1->getfp()->y() - p1->getrp()->y())*(p1->getfp()->y() - p1->getrp()->y()));
							double l2 = sqrt((p2->getfp()->x() - p2->getrp()->x())*(p2->getfp()->x() - p2->getrp()->x()) + 
								(p2->getfp()->y() - p2->getrp()->y())*(p2->getfp()->y() - p2->getrp()->y()));
							double l3 = sqrt((p3->getfp()->x() - p3->getrp()->x())*(p3->getfp()->x() - p3->getrp()->x()) + 
								(p3->getfp()->y() - p3->getrp()->y())*(p3->getfp()->y() - p3->getrp()->y()));
							if      (ang1<B_ANGLE/2 || l1<BD)
							{
								cout<<"    -> additional correction:";
								int adp1 = pick_correction(p1);
								if (adp1>=0) {return adp1;}
							}
							else if (ang2<B_ANGLE/2 || l2<BD)
							{
								cout<<"    -> additional correction:";
								int adp2 = pick_correction(p2);
								if (adp2>=0) {return adp2;}
							}
							else if (ang3<B_ANGLE/2 || l3<BD)
							{
								cout<<"    -> additional correction:";
								int adp3 = pick_correction(p3);
								if (adp3>=0) {return adp3;}
							}
						}
						else if (p12n && !p22n && !p32n)
						{
							double ang1 = p1->point_angle();
							double ang2 = p2->point_angle();
							double ang3 = p3->point_angle();
							if      (ang1<ang2 && ang1<ang3 && ang1<B_ANGLE/2)
							{
								cout<<"    -> additional correction:";
								int adp1 = pick_correction(p1);
								if (adp1>=0) {return adp1;}
							}
							else if (ang2<ang3 && ang2<B_ANGLE)                
							{
								cout<<"    -> additional correction:";
								int adp2 = pick_correction(p2);
								if (adp2>=0) {return adp2;}
							}
							else if (ang3<ang2 && ang3<B_ANGLE)                
							{
								cout<<"    -> additional correction:";
								int adp3 = pick_correction(p3);
								if (adp3>=0) {return adp3;}
							}
						}
						else if (!p12n && p22n && !p32n)
						{
							double ang2 = p2->point_angle();
							double ang1 = p1->point_angle();
							double ang3 = p3->point_angle();
							if      (ang2<ang1 && ang2<ang3 && ang2<B_ANGLE/2)
							{
								cout<<"    -> additional correction:";
								int adp2 = pick_correction(p2);
								if (adp2>=0) {return adp2;}
							}
							else if (ang1<ang3 && ang1<B_ANGLE)                
							{
								cout<<"    -> additional correction:";
								int adp1 = pick_correction(p1);
								if (adp1>=0) {return adp1;}
							}
							else if (ang3<ang1 && ang3<B_ANGLE)                
							{
								cout<<"    -> additional correction:";
								int adp3 = pick_correction(p3);
								if (adp3>=0) {return adp3;}
							}
						}
						else if (!p12n && !p22n && p32n)
						{
							double ang3 = p3->point_angle();
							double ang1 = p1->point_angle();
							double ang2 = p2->point_angle();
							if      (ang3<ang1 && ang3<ang2 && ang3<B_ANGLE/2)
							{
								cout<<"    -> additional correction:";
								int adp3 = pick_correction(p3);
								if (adp3>=0) {return adp3;}
							}
							else if (ang1<ang2 && ang1<B_ANGLE)                
							{
								cout<<"    -> additional correction:";
								int adp1 = pick_correction(p1);
								if (adp1>=0) {return adp1;}
							}
							else if (ang2<ang1 && ang2<B_ANGLE)                
							{
								cout<<"    -> additional correction:";
								int adp2 = pick_correction(p2);
								if (adp2>=0) {return adp2;}
							}
						}
					}
					//
					cell_interior_resample(C1,0);
					cell_interior_resample(C2,0);
					cell_interior_resample(C3,0);
				}
			}
			else if (P->getab()->get_attach() && !P->getba()->get_attach())
			{
				point3D *s2 = P->getab()->get_Neighbor()->p1();
				point3D *t2 = P->getab()->get_Neighbor()->p2();
				cell *C1 = P->getba()->Cell();
				cell *C2 = P->getab()->get_Neighbor()->Cell();
				bool kill_C1 = false;
				int R_mpn = (int)R->getmp()->size();
				if (R_mpn>0)
				{
					int c2pn = (int)C2->get_pairs()->size();
					for (int i=0;i<R_mpn;i++)
					{
						cell *CRm = R->getmp()->at(i)->getab()->Cell();
						for (int j=0;j<c2pn;j++)
						{
							if (C2->get_pairs()->at(j)->get_redundant()) continue;
							if ((C2->get_pairs()->at(j)->get_I1()==C2 &&
								C2->get_pairs()->at(j)->get_I2()==CRm) ||
								(C2->get_pairs()->at(j)->get_I2()==C2 &&
								C2->get_pairs()->at(j)->get_I1()==CRm))
							{
								if ((int)C2->get_pairs()->at(j)->MP()->size()>0)
								{
									point3D *c2pn_s1 = C2->get_pairs()->at(j)->MP()->at(0)->S1();
									point3D *c2pn_t1 = C2->get_pairs()->at(j)->MP()->at(0)->T1();
									for (int k=0;k<(int)c2pn_s1->getmp()->size();k++)
									{
										if (c2pn_s1->getmp()->at(k)->getab()->Cell()==C1) {kill_C1 = true;break;}
									}
									for (int k=0;k<(int)c2pn_t1->getmp()->size();k++)
									{
										if (c2pn_t1->getmp()->at(k)->getab()->Cell()==C1) {kill_C1 = true;break;}
									}
								}
								break;
							}
						}
					}
				}
				if      (kill_C1)
				{
					cout<<", kill cell "<<C1->id()<<endl;
					cell_death_response(C1);
				}
				else if (!kill_C1)
				{
					cout<<", cells:"<<C1->id()<<","<<C2->id()<<endl;
					double xm = (R->x() + F->x())*0.5;
					double ym = (R->y() + F->y())*0.5;
					R->setfp(F->getfp());
					F->getfp()->setrp(R);
					R->setab(F->getab());
					F->getab()->reset_p1(R);
					R->setx(xm);
					R->sety(ym);
					C1->removeside(P->getba());
					C1->removeside(P->getab());
					vector<point3D*> Rmp;
					vector<point3D*> Fmp;
					for (int i=0;i<(int)R->getmp()->size();i++) {Rmp.push_back(R->getmp()->at(i));}
					for (int i=0;i<(int)F->getmp()->size();i++) {Fmp.push_back(F->getmp()->at(i));F->getmp()->at(i)->removemp(F);}
					for (int i=0;i<(int)P->getmp()->size();i++) {P->getmp()->at(i)->removemp(P);}
					node_remove_1(F);
					node_remove_1(P);
					node_merge(s2,R);
					int c1pn = (int)C1->get_pairs()->size();
					for (int i=0;i<c1pn;i++)
					{
						interpair *c1pi = C1->get_pairs()->at(i);
						if ((c1pi->get_I1()==C1 && c1pi->get_I2()!=C2) ||
							(c1pi->get_I2()==C1 && c1pi->get_I1()!=C2))
						{
							for (int j=0;j<(int)c1pi->MP()->size();j++)
							{
								if ((c1pi->MP()->at(j)->S1()==P && c1pi->MP()->at(j)->T1()==P) || 
									(c1pi->MP()->at(j)->S2()==P && c1pi->MP()->at(j)->T2()==P))
								{
									c1pi->remove_MP(c1pi->MP()->at(j));
								}
								else if (c1pi->MP()->at(j)->S1()==F)
								{
									c1pi->MP()->at(j)->setS1(R);
									if (c1pi->MP()->at(j)->T1()==F) {c1pi->MP()->at(j)->setT1(R);}
								}
								else if (c1pi->MP()->at(j)->S2()==F)
								{
									c1pi->MP()->at(j)->setS2(R);
									if (c1pi->MP()->at(j)->T2()==F) {c1pi->MP()->at(j)->setT2(R);}
								}
							}
						}
						else if ((c1pi->get_I1()==C1 && c1pi->get_I2()==C2) ||
							(c1pi->get_I2()==C1 && c1pi->get_I1()==C2))
						{
							for (int j=0;j<(int)c1pi->MP()->size();j++)
							{
								if (c1pi->MP()->at(j)->S1()==P)
								{
									c1pi->MP()->at(j)->setS1(R);
									c1pi->MP()->at(j)->setT2(s2);
								}
								if (c1pi->MP()->at(j)->S2()==P)
								{
									c1pi->MP()->at(j)->setS2(R);
									c1pi->MP()->at(j)->setT1(s2);
								}
								if (c1pi->MP()->at(j)->T1()==F) {c1pi->MP()->at(j)->setT1(R);}
								if (c1pi->MP()->at(j)->T2()==F) {c1pi->MP()->at(j)->setT2(R);}
							}
						}
					}
					s2->getab()->set_attach(0);
					s2->getab()->set_Neighbor(NULL);
					int Fmpn = (int)Fmp.size();
					if (Fmpn==0)
					{
						for (int i=0;i<(int)Rmp.size();i++)
						{
							Rmp[i]->setx(xm);
							Rmp[i]->sety(ym);
						}
					}
					else
					{
						for (int i=0;i<Fmpn;i++)
						{
							Fmp[i]->setx(xm);
							Fmp[i]->sety(ym);
							cell *C1F = Fmp[i]->getba()->Cell();
							for (int j=0;j<(int)Rmp.size();j++)
							{
								Rmp[j]->setx(xm);
								Rmp[j]->sety(ym);
								cell *C1R = Rmp[j]->getab()->Cell();
								if (C1R==C1F) continue;
								bool flag = true;
								for (int k=0;k<(int)C1F->get_pairs()->size();k++)
								{
									if (C1F->get_pairs()->at(k)->get_redundant()) continue;
									if ((C1F->get_pairs()->at(k)->get_I1()==C1F && C1F->get_pairs()->at(k)->get_I2()==C1R) ||
										(C1F->get_pairs()->at(k)->get_I2()==C1F && C1F->get_pairs()->at(k)->get_I1()==C1R))
									{
										flag = false;
										if (C1F->get_pairs()->at(k)->MP()->size()==0)
										{
											if (C1F->get_pairs()->at(k)->get_I1()==C1F)
											{
												mergepair *MP = new mergepair(0,Fmp[i],Fmp[i],Rmp[j],Rmp[j]);
												C1F->get_pairs()->at(k)->push_MP(MP);
											}
											else
											{
												mergepair *MP = new mergepair(0,Rmp[j],Rmp[j],Fmp[i],Fmp[i]);
												C1F->get_pairs()->at(k)->push_MP(MP);
											}
										}
										break;
									}
								}
								if (flag)
								{
									int pair_n = (int)collisionpairList.size();
									interpair *P = new interpair(pair_n,C1F,C1R);
									collisionpairList.push_back(P);
									//int iptype = interpair_type(C1F,C1R);
									//collisionpairList[pair_n]->set_adhesion(adhesion_pair_class[iptype]);
									double adhesion_force = adhesion_pair_array[C1F->get_cell_type()][C1R->get_cell_type()];
									collisionpairList[pair_n]->set_adhesion(adhesion_force);
									collisionpairList[pair_n]->set_friction(adhesion_force);
									mergepair *MP = new mergepair(0,Fmp[i],Fmp[i],Rmp[j],Rmp[j]);
									collisionpairList[pair_n]->push_MP(MP);
									C1F->pushpair(collisionpairList[pair_n]);
									C1R->pushpair(collisionpairList[pair_n]);
								}
								Rmp[j]->pushmp(Fmp[i]);
								Fmp[i]->pushmp(Rmp[j]);
							}
							R->pushmp(Fmp[i]);
							Fmp[i]->pushmp(R);
						}
					}
					Rmp.clear();
					Fmp.clear();
					cell_interior_resample(C1,0);
					cell_interior_resample(C2,0);
				}
			}
			else if (!P->getab()->get_attach() && P->getba()->get_attach())
			{
				point3D *s1 = P->getba()->get_Neighbor()->p1();
				point3D *t1 = P->getba()->get_Neighbor()->p2();
				cell *C1 = P->getab()->Cell();
				cell *C2 = s1->getab()->Cell();
				bool kill_C1 = false;
				int F_mpn = (int)F->getmp()->size();
				if (F_mpn>0)
				{
					int c2pn = (int)C2->get_pairs()->size();
					for (int i=0;i<F_mpn;i++)
					{
						cell *CFm = F->getmp()->at(i)->getab()->Cell();
						for (int j=0;j<c2pn;j++)
						{
							if (C2->get_pairs()->at(j)->get_redundant()) continue;
							if ((C2->get_pairs()->at(j)->get_I1()==C2 &&
								C2->get_pairs()->at(j)->get_I2()==CFm) ||
								(C2->get_pairs()->at(j)->get_I2()==C2 &&
								C2->get_pairs()->at(j)->get_I1()==CFm))
							{
								if ((int)C2->get_pairs()->at(j)->MP()->size()>0)
								{
									point3D *c2pn_s1 = C2->get_pairs()->at(j)->MP()->at(0)->S1();
									point3D *c2pn_t1 = C2->get_pairs()->at(j)->MP()->at(0)->T1();
									for (int k=0;k<(int)c2pn_s1->getmp()->size();k++)
									{
										if (c2pn_s1->getmp()->at(k)->getab()->Cell()==C1) {kill_C1 = true;break;}
									}
									for (int k=0;k<(int)c2pn_t1->getmp()->size();k++)
									{
										if (c2pn_t1->getmp()->at(k)->getab()->Cell()==C1) {kill_C1 = true;break;}
									}
								}
								break;
							}
						}
					}
				}
				if      (kill_C1)
				{
					cout<<", kill cell "<<C1->id()<<endl;
					cell_death_response(C1);
				}
				else if (!kill_C1)
				{
					cout<<", cells:"<<C1->id()<<","<<C2->id()<<endl;
					double xm = (R->x() + F->x())*0.5;
					double ym = (R->y() + F->y())*0.5;
					R->setfp(F->getfp());
					F->getfp()->setrp(R);
					R->setab(F->getab());
					F->getab()->reset_p1(R);
					R->setx(xm);
					R->sety(ym);
					C1->removeside(P->getba());
					C1->removeside(P->getab());
					vector<point3D*> Rmp;
					vector<point3D*> Fmp;
					for (int i=0;i<(int)R->getmp()->size();i++) {Rmp.push_back(R->getmp()->at(i));}
					for (int i=0;i<(int)F->getmp()->size();i++) {Fmp.push_back(F->getmp()->at(i));F->getmp()->at(i)->removemp(F);}
					for (int i=0;i<(int)P->getmp()->size();i++) {P->getmp()->at(i)->removemp(P);}
					node_merge(t1,F);
					node_remove_1(F);
					node_remove_1(P);
					int c1pn = (int)C1->get_pairs()->size();
					for (int i=0;i<c1pn;i++)
					{
						interpair *c1pi = C1->get_pairs()->at(i);
						if ((c1pi->get_I1()==C1 && c1pi->get_I2()!=C2) ||
							(c1pi->get_I2()==C1 && c1pi->get_I1()!=C2))
						{
							for (int j=0;j<(int)c1pi->MP()->size();j++)
							{
								if ((c1pi->MP()->at(j)->S1()==P && c1pi->MP()->at(j)->T1()==P) ||
									(c1pi->MP()->at(j)->S2()==P && c1pi->MP()->at(j)->T2()==P))
								{
									c1pi->remove_MP(c1pi->MP()->at(j));
								}
								else if (c1pi->MP()->at(j)->S1()==F)
								{
									c1pi->MP()->at(j)->setS1(R);
									if (c1pi->MP()->at(j)->T1()==F) {c1pi->MP()->at(j)->setT1(R);}
								}
								else if (c1pi->MP()->at(j)->S2()==F) 
								{
									c1pi->MP()->at(j)->setS2(R);
									if (c1pi->MP()->at(j)->T2()==F) {c1pi->MP()->at(j)->setT2(R);}
								}
							}
						}
						else if ((c1pi->get_I1()==C1 && c1pi->get_I2()==C2) ||
							(c1pi->get_I2()==C1 && c1pi->get_I1()==C2))
						{
							for (int j=0;j<(int)c1pi->MP()->size();j++)
							{
								if (c1pi->MP()->at(j)->T1()==P)
								{
									c1pi->MP()->at(j)->setT1(R);
									c1pi->MP()->at(j)->setS2(t1);
								}
								if (c1pi->MP()->at(j)->T2()==P)
								{
									c1pi->MP()->at(j)->setT2(R);
									c1pi->MP()->at(j)->setS1(t1);
								}
							}
						}
					}
					s1->getab()->set_attach(0);
					s1->getab()->set_Neighbor(NULL);
					int Fmpn = (int)Fmp.size();
					if (Fmpn==0) 
					{
						for (int i=0;i<(int)Rmp.size();i++)
						{
							Rmp[i]->setx(xm);
							Rmp[i]->sety(ym);
						}
					}
					else
					{
						for (int i=0;i<Fmpn;i++)
						{
							Fmp[i]->setx(xm);
							Fmp[i]->sety(ym);
							cell *C1F = Fmp[i]->getba()->Cell();
							for (int j=0;j<(int)Rmp.size();j++)
							{
								Rmp[j]->setx(xm);
								Rmp[j]->sety(ym);
								cell *C1R = Rmp[j]->getab()->Cell();
								if (C1R==C1F) continue;
								bool flag = true;
								int c1fpn = (int)C1F->get_pairs()->size();
								for (int k=0;k<c1fpn;k++)
								{
									if (C1F->get_pairs()->at(k)->get_redundant()) continue;
									if ((C1F->get_pairs()->at(k)->get_I1()==C1F && C1F->get_pairs()->at(k)->get_I2()==C1R) ||
										(C1F->get_pairs()->at(k)->get_I2()==C1F && C1F->get_pairs()->at(k)->get_I1()==C1R))
									{
										flag = false;
										if ((int)C1F->get_pairs()->at(k)->MP()->size()==0)
										{
											if (C1F->get_pairs()->at(k)->get_I1()==C1F)
											{
												mergepair *MP = new mergepair(0,Fmp[i],Fmp[i],Rmp[j],Rmp[j]);
												C1F->get_pairs()->at(k)->push_MP(MP);
											}
											else
											{
												mergepair *MP = new mergepair(0,Rmp[j],Rmp[j],Fmp[i],Fmp[i]);
												C1F->get_pairs()->at(k)->push_MP(MP);
											}
										}
										break;
									}
								}
								if (flag)
								{
									int pair_n = (int)collisionpairList.size();
									interpair *P = new interpair(pair_n,C1F,C1R);
									collisionpairList.push_back(P);
									//int iptype = interpair_type(C1F,C1R);
									//collisionpairList[pair_n]->set_adhesion(adhesion_pair_class[iptype]);
									double adhesion_force = adhesion_pair_array[C1F->get_cell_type()][C1R->get_cell_type()];
									collisionpairList[pair_n]->set_adhesion(adhesion_force);
									collisionpairList[pair_n]->set_friction(adhesion_force);
									mergepair *MP = new mergepair(0,Fmp[i],Fmp[i],Rmp[j],Rmp[j]);
									collisionpairList[pair_n]->push_MP(MP);
									C1F->pushpair(collisionpairList[pair_n]);
									C1R->pushpair(collisionpairList[pair_n]);
								}
								Rmp[j]->pushmp(Fmp[i]);
								Fmp[i]->pushmp(Rmp[j]);
							}
							R->pushmp(Fmp[i]);
							Fmp[i]->pushmp(R);
						}
					}
					Rmp.clear();
					Fmp.clear();
					cell_interior_resample(C1,0);
					cell_interior_resample(C2,0);
				}
			}
		}
	}
	return -1;
}

void dbReader::cell_interior_resample(cell* C, int time)
{
	C->set_interior_time(time);
	double range[4]; // 0:xmin 1:ymin 2:xmax 3:ymax
	range[0] = 1000000000000;
	range[1] = 1000000000000;
	range[2] =-1000000000000;
	range[3] =-1000000000000;
	
	for (int i=0;i<(int)C->get_sides()->size();i++) 
	{
		point3D *p1 = C->get_sides()->at(i)->p1();
		p1->set_migrate_mark(0);       // refresh migration mark
		p1->set_stored_force_vis(0,0); // refresh stored force
		double vx = p1->x();
		double vy = p1->y();
		if (range[0]>vx) {range[0] = vx;}
		if (range[1]>vy) {range[1] = vy;}
		if (range[2]<vx) {range[2] = vx;}
		if (range[3]<vy) {range[3] = vy;}
	}
	range[0] -= 1000;
	range[1] -= 1000;
	range[2] += 1000;
	range[3] += 1000;

	CD3DW *Del = new CD3DW(range);
	int size = (int)C->get_sides()->size();
	for (int i=0;i<size;i++)
	{
		C->get_sides()->at(i)->p1()->clear_inner_at();
		Del->add_resample(C->get_sides()->at(i)->p1()->x(),
				 C->get_sides()->at(i)->p1()->y(),
				 BD*BD,
				 i+1,
				 C->get_sides()->at(i)->p1());
	}
	Del->add_interior(BD*BD);
	C->clear_inner_t();
	C->clear_inner_p();
	C->clear_inner_p_slip();
	double lame_MU = C->get_lame(0);
	double lame_LAMBDA = C->get_lame(1);
	int t_n = 0;
	int p_slip_n = 0;
	int p_n = (int)C->get_sides()->size();
	for (int i=0;i<(int)Del->get_Cs()->size();i++)
	{
		if (Del->get_Cs()->at(i)->BN() && !Del->get_Cs()->at(i)->get_type()) // Delaunay triangle
		{
			triangle *A = new triangle(t_n,
				Del->get_Cs()->at(i)->get_VV(0)->P(),
				Del->get_Cs()->at(i)->get_VV(1)->P(), 
				Del->get_Cs()->at(i)->get_VV(2)->P());
			A->set_alpha(Del->get_Cs()->at(i)->get_alphav());
			A->set_center(Del->get_Cs()->at(i)->get_center(0),Del->get_Cs()->at(i)->get_center(1));
			A->set_lame(0,lame_MU);
			A->set_lame(1,lame_LAMBDA);
			C->pushtriangle(A);
			A->getA()->push_inner_at(A);
			A->getB()->push_inner_at(A);
			A->getC()->push_inner_at(A);
			if (A->getA()->get_cell_boundary() && 
				A->getB()->get_cell_boundary() &&
				A->getC()->get_cell_boundary())
			{
				if ((A->getA()->getfp()==A->getB() && A->getB()->getfp()==A->getC()) ||
					(A->getA()->getfp()==A->getC() && A->getC()->getfp()==A->getB()) ||
					(A->getB()->getfp()==A->getA() && A->getA()->getfp()==A->getC()) ||
					(A->getB()->getfp()==A->getC() && A->getC()->getfp()==A->getA()) ||
					(A->getC()->getfp()==A->getA() && A->getA()->getfp()==A->getB()) ||
					(A->getC()->getfp()==A->getB() && A->getB()->getfp()==A->getC()))
				{
					point3D* P = new point3D(p_slip_n,(A->getA()->x()+A->getB()->x()+A->getC()->x())/3,(A->getA()->y()+A->getB()->y()+A->getC()->y())/3);
					P->set_cell_boundary(0);
					P->setCell(C);
					C->pushinnerpoislip(P);
					p_slip_n++;
					A->set_pick(1);
				}
			}
			t_n++;
		}
	}
	for (int i=0;i<(int)Del->get_Vs()->size();i++)
	{
		if (i<p_n) continue;
		Del->get_Vs()->at(i)->P()->setCell(C);
		bool add = false;
		for (int j=0;j<(int)Del->get_Vs()->at(i)->P()->get_inner_at()->size();j++)
		{
			if (Del->get_Vs()->at(i)->P()->get_inner_at()->at(j)->getA()->get_cell_boundary() ||
				Del->get_Vs()->at(i)->P()->get_inner_at()->at(j)->getB()->get_cell_boundary() ||
				Del->get_Vs()->at(i)->P()->get_inner_at()->at(j)->getC()->get_cell_boundary())
			{add = true;break;}
		}
		if (add)
		{
			Del->get_Vs()->at(i)->P()->set_burry(0);
			C->pushinnerpoi(Del->get_Vs()->at(i)->P());
		}
		else
		{
			Del->get_Vs()->at(i)->P()->set_burry(1);
			C->pushinnerpoi(Del->get_Vs()->at(i)->P());
		}
	}
	C->set_inner_p_n();
	Del->~CD3DW();
	C->set_interior_refresh(0);
}

void dbReader::cell_simple_relaxation(cell *C, int time)
{
	double tension_e = 0;
	double pressure_e = 0;
	double mass_e = C->get_mass();
	if (C->get_migrate_relax())
	{
		tension_e = C->get_tcoef();
		pressure_e = C->get_pcoef();
		int sn = (int)C->get_sides()->size();
		int flagtime = 0;
		bool another_r = false;
		while (flagtime<3)
		{
			flagtime++;
			for (int i=0;i<sn;i++)
			{
				point3D *p1 = C->get_sides()->at(i)->p1();
				node *N1 = p1->get_node_id();
				double Force_x = 0;
				double Force_y = 0;
				int N1vn = (int)N1->getvertex()->size();
				if (N1vn<=2)
				{
					if (N1vn==1 && flagtime==2)
					{
						double p_ang = p1->point_angle();
						if (p_ang<30 || p_ang>180) {another_r = true;}
					}
					for (int j=0;j<N1vn;j++)
					{
						point3D *pt = N1->getvertex()->at(j);
						cell *Cpt = pt->getab()->Cell();
						if (Cpt->Soften()) continue;
						double ab_len = pt->getab()->getlength();
						double ba_len = pt->getba()->getlength();
						double ab_x = pt->getab()->getnormal(0);
						double ab_y = pt->getab()->getnormal(1);
						double ba_x = pt->getba()->getnormal(0);
						double ba_y = pt->getba()->getnormal(1);
						double ab_d = sqrt(ab_x*ab_x + ab_y*ab_y);
						double ba_d = sqrt(ba_x*ba_x + ba_y*ba_y);
						double ab_nx = ab_x/ab_d;
						double ab_ny = ab_y/ab_d;
						double ba_nx = ba_x/ba_d;
						double ba_ny = ba_y/ba_d;
						double T_ab_x = tension_e*(pt->getfp()->x() - pt->x());
						double T_ab_y = tension_e*(pt->getfp()->y() - pt->y());
						double T_ba_x = tension_e*(pt->getrp()->x() - pt->x());
						double T_ba_y = tension_e*(pt->getrp()->y() - pt->y());
						double P_ab_x = 0.5*pressure_e*ab_nx*ab_len;
						double P_ab_y = 0.5*pressure_e*ab_ny*ab_len;
						double P_ba_x = 0.5*pressure_e*ba_nx*ba_len;
						double P_ba_y = 0.5*pressure_e*ba_ny*ba_len;
						Force_x += T_ab_x + T_ba_x + P_ab_x + P_ba_x;
						Force_y += T_ab_y + T_ba_y + P_ab_y + P_ba_y;
					}
					double ab_len = p1->getab()->getlength();
					double ba_len = p1->getba()->getlength();
					double dpx = 2*Force_x/(ab_len + ba_len)/mass_e*TM*TM/4;
					double dpy = 2*Force_y/(ab_len + ba_len)/mass_e*TM*TM/4;
					p1->setDp(dpx,dpy);
				}
				else if (N1vn>2)
				{
					edge *p1_ab = p1->getab();
					edge *p1_ba = p1->getba();
					double p1_ab_len = p1_ab->getlength();
					double p1_ba_len = p1_ba->getlength();
					double p1_min_len = p1_ab_len;if (p1_ba_len<p1_ab_len) {p1_min_len = p1_ba_len;}
					for (int j=0;j<N1vn;j++)
					{
						point3D *pt = N1->getvertex()->at(j);
						double ab_len = 0;
						double ba_len = 0;
						if (pt==p1)
						{
							ab_len = p1_ab_len;
							ba_len = p1_ba_len;
						}
						else
						{
							if (pt->getab()->get_attach() &&
							    pt->getab()->get_Neighbor()==p1_ba)
							{ab_len = p1_ba_len;}
							else
							{ab_len = p1_min_len;}
							if (pt->getba()->get_attach() &&
							    pt->getba()->get_Neighbor()==p1_ab)
							{ba_len = p1_ab_len;}
							else
							{ba_len = p1_min_len;}
						}
						cell *Cpt = pt->getab()->Cell();
						if (Cpt->Soften()) continue;
						double ab_len_r = pt->getab()->getlength();
						double ba_len_r = pt->getba()->getlength();
						double ab_x = pt->getab()->getnormal(0);
						double ab_y = pt->getab()->getnormal(1);
						double ba_x = pt->getba()->getnormal(0);
						double ba_y = pt->getba()->getnormal(1);
						double ab_d = sqrt(ab_x*ab_x + ab_y*ab_y);
						double ba_d = sqrt(ba_x*ba_x + ba_y*ba_y);
						double ab_nx = ab_x/ab_d;
						double ab_ny = ab_y/ab_d;
						double ba_nx = ba_x/ba_d;
						double ba_ny = ba_y/ba_d;
						double T_ab_x = tension_e*(pt->getfp()->x() - pt->x())*ab_len/ab_len_r;
						double T_ab_y = tension_e*(pt->getfp()->y() - pt->y())*ab_len/ab_len_r;
						double T_ba_x = tension_e*(pt->getrp()->x() - pt->x())*ba_len/ba_len_r;
						double T_ba_y = tension_e*(pt->getrp()->y() - pt->y())*ba_len/ba_len_r;
						double P_ab_x = 0.5*pressure_e*ab_nx*ab_len;
						double P_ab_y = 0.5*pressure_e*ab_ny*ab_len;
						double P_ba_x = 0.5*pressure_e*ba_nx*ba_len;
						double P_ba_y = 0.5*pressure_e*ba_ny*ba_len;
						Force_x += T_ab_x + T_ba_x + P_ab_x + P_ba_x;
						Force_y += T_ab_y + T_ba_y + P_ab_y + P_ba_y;
					}
					double dpx = 2*Force_x/(p1_ab_len + p1_ba_len)/mass_e*TM*TM/4;
					double dpy = 2*Force_y/(p1_ab_len + p1_ba_len)/mass_e*TM*TM/4;
					p1->setDp(dpx,dpy);
				}
			}
			for (int i=0;i<sn;i++)
			{
				point3D *p1 = C->get_sides()->at(i)->p1();
				double dpx = p1->getDp(0);
				double dpy = p1->getDp(1);
				double px = p1->x();
				double py = p1->y();
				p1->setx(px + dpx);
				p1->sety(py + dpy);
				int mpn = (int)p1->getmp()->size();
				for (int j=0;j<mpn;j++)
				{
					point3D *pm = p1->getmp()->at(j);
					double pmx = pm->x();
					double pmy = pm->y();
					pm->setx(pmx + dpx);
					pm->sety(pmy + dpy);
				}
			}
		}
		if (another_r)
		{
			flagtime = 0;
			while (flagtime<3)
			{
				flagtime++;
				for (int i=0;i<sn;i++)
				{
					point3D *p1 = C->get_sides()->at(i)->p1();
					node *N1 = p1->get_node_id();
					double Force_x = 0;
					double Force_y = 0;
					int N1vn = (int)N1->getvertex()->size();
					if (N1vn<=2)
					{
						for (int j=0;j<N1vn;j++)
						{
							point3D *pt = N1->getvertex()->at(j);
							cell *Cpt = pt->getab()->Cell();
							if (Cpt->Soften()) continue;
							double ab_len = pt->getab()->getlength();
							double ba_len = pt->getba()->getlength();
							double ab_x = pt->getab()->getnormal(0);
							double ab_y = pt->getab()->getnormal(1);
							double ba_x = pt->getba()->getnormal(0);
							double ba_y = pt->getba()->getnormal(1);
							double ab_d = sqrt(ab_x*ab_x + ab_y*ab_y);
							double ba_d = sqrt(ba_x*ba_x + ba_y*ba_y);
							double ab_nx = ab_x/ab_d;
							double ab_ny = ab_y/ab_d;
							double ba_nx = ba_x/ba_d;
							double ba_ny = ba_y/ba_d;
							double T_ab_x = tension_e*(pt->getfp()->x() - pt->x());
							double T_ab_y = tension_e*(pt->getfp()->y() - pt->y());
							double T_ba_x = tension_e*(pt->getrp()->x() - pt->x());
							double T_ba_y = tension_e*(pt->getrp()->y() - pt->y());
							double P_ab_x = 0.5*pressure_e*ab_nx*ab_len;
							double P_ab_y = 0.5*pressure_e*ab_ny*ab_len;
							double P_ba_x = 0.5*pressure_e*ba_nx*ba_len;
							double P_ba_y = 0.5*pressure_e*ba_ny*ba_len;
							Force_x += T_ab_x + T_ba_x + P_ab_x + P_ba_x;
							Force_y += T_ab_y + T_ba_y + P_ab_y + P_ba_y;
						}
						double ab_len = p1->getab()->getlength();
						double ba_len = p1->getba()->getlength();
						double dpx = 2*Force_x/(ab_len + ba_len)/mass_e*TM*TM/4;
						double dpy = 2*Force_y/(ab_len + ba_len)/mass_e*TM*TM/4;
						p1->setDp(dpx,dpy);
					}
					else if (N1vn>2)
					{
						edge *p1_ab = p1->getab();
						edge *p1_ba = p1->getba();
						double p1_ab_len = p1_ab->getlength();
						double p1_ba_len = p1_ba->getlength();
						double p1_min_len = p1_ab_len;if (p1_ba_len<p1_ab_len) {p1_min_len = p1_ba_len;}
						for (int j=0;j<N1vn;j++)
						{
							point3D *pt = N1->getvertex()->at(j);
							double ab_len = 0;
							double ba_len = 0;
							if (pt==p1)
							{
								ab_len = p1_ab_len;
								ba_len = p1_ba_len;
							}
							else
							{
								if (pt->getab()->get_attach() &&
									pt->getab()->get_Neighbor()==p1_ba)
								{ab_len = p1_ba_len;}
								else
								{ab_len = p1_min_len;}
								if (pt->getba()->get_attach() &&
									pt->getba()->get_Neighbor()==p1_ab)
								{ba_len = p1_ab_len;}
								else
								{ba_len = p1_min_len;}
							}
							cell *Cpt = pt->getab()->Cell();
							if (Cpt->Soften()) continue;
							double ab_len_r = pt->getab()->getlength();
							double ba_len_r = pt->getba()->getlength();
							double ab_x = pt->getab()->getnormal(0);
							double ab_y = pt->getab()->getnormal(1);
							double ba_x = pt->getba()->getnormal(0);
							double ba_y = pt->getba()->getnormal(1);
							double ab_d = sqrt(ab_x*ab_x + ab_y*ab_y);
							double ba_d = sqrt(ba_x*ba_x + ba_y*ba_y);
							double ab_nx = ab_x/ab_d;
							double ab_ny = ab_y/ab_d;
							double ba_nx = ba_x/ba_d;
							double ba_ny = ba_y/ba_d;
							double T_ab_x = tension_e*(pt->getfp()->x() - pt->x())*ab_len/ab_len_r;
							double T_ab_y = tension_e*(pt->getfp()->y() - pt->y())*ab_len/ab_len_r;
							double T_ba_x = tension_e*(pt->getrp()->x() - pt->x())*ba_len/ba_len_r;
							double T_ba_y = tension_e*(pt->getrp()->y() - pt->y())*ba_len/ba_len_r;
							double P_ab_x = 0.5*pressure_e*ab_nx*ab_len;
							double P_ab_y = 0.5*pressure_e*ab_ny*ab_len;
							double P_ba_x = 0.5*pressure_e*ba_nx*ba_len;
							double P_ba_y = 0.5*pressure_e*ba_ny*ba_len;
							Force_x += T_ab_x + T_ba_x + P_ab_x + P_ba_x;
							Force_y += T_ab_y + T_ba_y + P_ab_y + P_ba_y;
						}
						double dpx = 2*Force_x/(p1_ab_len + p1_ba_len)/mass_e*TM*TM/4;
						double dpy = 2*Force_y/(p1_ab_len + p1_ba_len)/mass_e*TM*TM/4;
						p1->setDp(dpx,dpy);
					}
				}
				for (int i=0;i<sn;i++)
				{
					point3D *p1 = C->get_sides()->at(i)->p1();
					double dpx = p1->getDp(0);
					double dpy = p1->getDp(1);
					double px = p1->x();
					double py = p1->y();
					p1->setx(px + dpx);
					p1->sety(py + dpy);
					int mpn = (int)p1->getmp()->size();
					for (int j=0;j<mpn;j++)
					{
						point3D *pm = p1->getmp()->at(j);
						double pmx = pm->x();
						double pmy = pm->y();
						pm->setx(pmx + dpx);
						pm->sety(pmy + dpy);
					}
				}
			}
		}
	}
	else if (C->Soften())
	{
		tension_e = tension_edge_class[7];
		pressure_e = pressure_edge_class[7];
		int sn = (int)C->get_sides()->size();
		int flagtime = 0;
		while (flagtime<4)
		{
			flagtime++;
			for (int i=0;i<sn;i++)
			{
				point3D *pt = C->get_sides()->at(i)->p1();
				int mptn = (int)pt->getmp()->size();
				if (!pt->getab()->get_attach() && !pt->getba()->get_attach() && mptn==0)
				{
					double ab_len = pt->getab()->getlength();
					double ba_len = pt->getba()->getlength();
					double ab_x = pt->getab()->getnormal(0);
					double ab_y = pt->getab()->getnormal(1);
					double ba_x = pt->getba()->getnormal(0);
					double ba_y = pt->getba()->getnormal(1);
					double ab_d = sqrt(ab_x*ab_x + ab_y*ab_y);
					double ba_d = sqrt(ba_x*ba_x + ba_y*ba_y);
					double ab_nx = ab_x/ab_d;
					double ab_ny = ab_y/ab_d;
					double ba_nx = ba_x/ba_d;
					double ba_ny = ba_y/ba_d;
					double T_ab_x = tension_e*(pt->getfp()->x() - pt->x());
					double T_ab_y = tension_e*(pt->getfp()->y() - pt->y());
					double T_ba_x = tension_e*(pt->getrp()->x() - pt->x());
					double T_ba_y = tension_e*(pt->getrp()->y() - pt->y());
					double P_ab_x = 0.5*pressure_e*ab_nx*ab_len;
					double P_ab_y = 0.5*pressure_e*ab_ny*ab_len;
					double P_ba_x = 0.5*pressure_e*ba_nx*ba_len;
					double P_ba_y = 0.5*pressure_e*ba_ny*ba_len;
					double Force_x = T_ab_x + T_ba_x + P_ab_x + P_ba_x;
					double Force_y = T_ab_y + T_ba_y + P_ab_y + P_ba_y;
					double dpx = 2*Force_x/(ab_len + ba_len)/mass_e*TM*TM;
					double dpy = 2*Force_y/(ab_len + ba_len)/mass_e*TM*TM;
					pt->setDp(dpx,dpy);
				}
			}
			for (int i=0;i<sn;i++)
			{
				point3D *pt = C->get_sides()->at(i)->p1();
				int mptn = (int)pt->getmp()->size();
				if (!pt->getab()->get_attach() && !pt->getba()->get_attach() && mptn==0)
				{
					double ptx = pt->x();
					double pty = pt->y();
					double ptdpx = pt->getDp(0);
					double ptdpy = pt->getDp(1);
					pt->setx(ptx + ptdpx);
					pt->sety(pty + ptdpy);
				}
			}
		}
	}
}

bool dbReader::cell_self_collision(cell *C, int time)
{
	bool valid = false;
	int sn = C->get_sides()->size();
	for (int i=0;i<sn-1;i++)
	{
		edge *Ei = C->get_sides()->at(i);
		point3D *pi1 = Ei->p1();
		point3D *pi2 = Ei->p2();
		for (int j=i+1;j<sn;j++)
		{
			edge *Ej = C->get_sides()->at(j);
			point3D *pj1 = Ej->p1();
			point3D *pj2 = Ej->p2();
			if (pj1!=pi2 && pj2!=pi1)
			{
				int intertype = intersection_type(pi1,pj2);
				if (intertype>=3 && intertype<=6)
				{
					valid = true;
					break;
				}
			}
		}
		if (valid) {break;}
	}
	return valid;
}

